+    @Override
+    public BlobCacheBufferedIndexInput clone() {
+        BlobCacheBufferedIndexInput clone = (BlobCacheBufferedIndexInput) super.clone();
+
+        clone.buffer = EMPTY_BYTEBUFFER;
+        clone.bufferStart = getFilePointer();
