+                for (int i = 0; i < BLOCK_LENGTH; i++) {
+                    for (int v = 0; v < valuesPerGroup; v++) {
+                        builder.appendDouble(i % GROUPS);
+                    }
+                }
+                yield builder.build();
+            }
+            case BOOLEANS -> {
+                BooleanBlock.Builder builder = BooleanBlock.newBlockBuilder(BLOCK_LENGTH);
